"use client";

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
import { UR } from "./ur";

export type Lang = "en" | "ur";

/** Navigation + common labels. Invoices and receipts stay English-only by design (PDF generated by the backend). */
const DICT: Record<Lang, Record<string, string>> = {
  en: {
    dashboard: "Dashboard", customers: "Customers", connections: "Connections", invoices: "Invoices", payments: "Payments",
    receipts: "Receipts", complaints: "Complaints", tasks: "Tasks", attendance: "Attendance & leave", inventory: "Inventory",
    expenses: "Expenses", leads: "Leads", reports: "Reports", cash: "Cash & corrections", notifications: "Notifications",
    employees: "Employees", packages: "Packages", audit: "Audit log", imports: "Data import", signOut: "Sign out",
    offices: "Offices & villages", openingBalances: "Opening balances", transfers: "Transfers", settings: "Settings",
    password: "Password", search: "Search", save: "Save", cancel: "Cancel", language: "اردو",
  },
  ur: {
    dashboard: "ڈیش بورڈ", customers: "صارفین", connections: "کنکشنز", invoices: "انوائسز", payments: "ادائیگیاں",
    receipts: "رسیدیں", complaints: "شکایات", tasks: "کام", attendance: "حاضری اور چھٹی", inventory: "اسٹاک",
    expenses: "اخراجات", leads: "نئے گاہک", reports: "رپورٹس", cash: "نقد اور اصلاحات", notifications: "اطلاعات",
    employees: "ملازمین", packages: "پیکجز", audit: "آڈٹ لاگ", imports: "ڈیٹا امپورٹ", signOut: "لاگ آؤٹ",
    offices: "دفاتر اور گاؤں", openingBalances: "ابتدائی بقایا", transfers: "منتقلیاں", settings: "سیٹنگز",
    password: "پاس ورڈ", search: "تلاش", save: "محفوظ کریں", cancel: "منسوخ", language: "English",
  },
};

export function translate(lang: Lang, text: string): string {
  return lang === "ur" ? (UR[text] ?? text) : text;
}

interface I18n { lang: Lang; t: (key: string) => string; tr: (text: string) => string; toggle: () => void }
const Ctx = createContext<I18n>({ lang: "en", t: (k) => k, tr: (x) => x, toggle: () => {} });

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState<Lang>("en");
  useEffect(() => {
    try {
      const saved = localStorage.getItem("isp-lang");
      if (saved === "ur" || saved === "en") setLang(saved);
    } catch { /* storage may be unavailable */ }
  }, []);
  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === "ur" ? "rtl" : "ltr";
  }, [lang]);
  const toggle = () => setLang((l) => {
    const next = l === "en" ? "ur" : "en";
    try { localStorage.setItem("isp-lang", next); } catch { /* ignore */ }
    return next;
  });
  return <Ctx.Provider value={{ lang, t: (k) => DICT[lang][k] ?? DICT.en[k] ?? k, tr: (x) => translate(lang, x), toggle }}>{children}</Ctx.Provider>;
}

export const useI18n = () => useContext(Ctx);
